import pandas as pd
from sklearn.cluster import KMeans
from sklearn.metrics import silhouette_score, davies_bouldin_score

# ==========================================
# STEP 1: LOAD THE PREPARED MATRIX
# ==========================================
print("Loading cleaned dataset...")
# Load the 25-column matrix generated by the cleaning pipeline
X_clean = pd.read_csv('H2_cleaned_for_clustering.csv')

# ==========================================
# STEP 2: RUN UNTUNED BASELINE MODEL
# ==========================================
print("Running baseline K-Means algorithm (k=3)...")
# For Milestone 1, we use an untuned baseline. We arbitrarily select 3 clusters.
# random_state=42 ensures the results are reproducible across your team.
kmeans = KMeans(n_clusters=3, random_state=42, n_init=10)

# fit_predict runs the math and assigns a cluster label (0, 1, or 2) to every guest
cluster_labels = kmeans.fit_predict(X_clean)

# Attach the resulting labels back to the dataframe for analysis
X_clean['Cluster_ID'] = cluster_labels

# ==========================================
# STEP 3: CALCULATE MILESTONE 1 METRICS
# ==========================================
print("\nCalculating evaluation metrics...")

# Davies-Bouldin Index (Lower is better). Measures separation between clusters.
db_index = davies_bouldin_score(X_clean.drop(columns=['Cluster_ID']), cluster_labels)
print(f"Davies-Bouldin Index: {db_index:.4f}")

# Silhouette Score (Closer to 1.0 is better). Measures how tight the clusters are.
# This requires O(N^2) memory. To satisfy computational constraints, we isolate a 
# random 10,000-row sample to prevent the processor from crashing.
X_sample = X_clean.sample(n=10000, random_state=42)
sil_score = silhouette_score(X_sample.drop(columns=['Cluster_ID']), X_sample['Cluster_ID'])
print(f"Silhouette Score (10k sample): {sil_score:.4f}")

# ==========================================
# STEP 4: EXTRACT CENTROIDS FOR INTERPRETATION
# ==========================================
print("\n--- CLUSTER AVERAGES (CENTROIDS) ---")
print("Use these values for the 'brief interpretation' section of the report:\n")

# Select a few key physical variables that easily describe a guest's behavior
key_features = [
    'LeadTime', 
    'ADR', 
    'StaysInWeekendNights', 
    'StaysInWeekNights', 
    'TotalOfSpecialRequests'
]

# Calculate the mean of these variables for each cluster group
centroids = X_clean.groupby('Cluster_ID')[key_features].mean()
print(centroids.round(2))

# Display the size of each cluster
print("\nNumber of guests in each cluster:")
print(X_clean['Cluster_ID'].value_counts())